import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s5-u01")
C = "B1"
# Lições de aprofundamento (10–24): conversas espontâneas em situações variadas.

L(10, "Conversa com um desconhecido", "Een praatje in de trein.",
  ["Iniciar e manter uma conversa curta com alguém que não conhece"],
  vocab=[V("v-een-praatje-maken","een praatje maken","meter conversa","expression"), V("v-onbekende","onbekende","desconhecido","noun","de","onbekenden"),
         V("v-zit-hier-iemand","zit hier iemand?","está alguém aqui sentado?","expression"), V("v-ook-onderweg","ook onderweg naar","também a caminho de","expression")],
  ex=[("In de trein maak ik soms een praatje met een onbekende.","No comboio às vezes meto conversa com um desconhecido."),("Pardon, zit hier iemand?","Desculpe, está alguém aqui sentado?"),("Bent u ook onderweg naar Amsterdam?","Também vai a caminho de Amesterdão?")],
  review=["v-o-ja","v-en-jij","v-trouwens"],
  cefr=C, exs=[
    MA([("een praatje maken","meter conversa"),("onbekende","desconhecido"),("zit hier iemand?","está alguém aqui?"),("trouwens","a propósito")], "Conversa.", ["v-een-praatje-maken","v-onbekende","v-zit-hier-iemand","v-trouwens"]),
    CO("dialogue","In de intercity", "Rui: Pardon, zit hier iemand?\nVrouw: Nee hoor, ga zitten.\nRui: Dank u. Bent u ook onderweg naar Amsterdam?\nVrouw: Ja, ik ga naar een concert in het Concertgebouw. En u?\nRui: Ik heb een sollicitatiegesprek. Ik ben een beetje zenuwachtig.\nVrouw: O, spannend! Wat voor werk is het?\nRui: Een baan als verpleegkundige.\nVrouw: Wat mooi! Mijn dochter is ook verpleegkundige. Veel succes!",
       [("Para onde vai a senhora?", ["*Um concerto","Uma entrevista","O trabalho"]),("Porque está o Rui nervoso?", ["*Tem uma entrevista de emprego","Perdeu o bilhete","Está atrasado"]),("Que ligação há entre eles?", ["*A filha dela também é enfermeira","São vizinhos","Trabalham juntos"])],
       "Conversa espontânea típica.", ["v-een-praatje-maken","v-zit-hier-iemand","v-ook-onderweg"]),
    TR("pt-nl","Desculpe, está alguém aqui sentado?", ["Pardon, zit hier iemand","Pardon, zit hier iemand?","Sorry, zit hier iemand"], "Fórmula.", ["v-zit-hier-iemand"]),
    TR("pt-nl","Também vai a caminho de Utrecht?", ["Bent u ook onderweg naar Utrecht","Ben je ook onderweg naar Utrecht","Gaat u ook naar Utrecht"], "onderweg naar.", ["v-ook-onderweg"]),
    MC("Nos Países Baixos, meter conversa com desconhecidos no comboio é…", ["*possível, mas muitas pessoas preferem sossego; observe os sinais","obrigatório|Não.","proibido|Não."], "Há carruagens de silêncio (stiltecoupé)!", ["v-een-praatje-maken"]),
    FE(["Ik","maak","graag","een","praatje","op","onbekenden."], 5, "met", "een praatje maken met.", ["v-een-praatje-maken"]),
    FB("Ik heb in de bus een leuk ___ gemaakt met een oudere meneer.", ["praatje"], "conversa.", ["v-een-praatje-maken"], choices=["praatje","onbekende","gesprekje"], tr="Meti uma conversa simpática no autocarro com um senhor mais velho."),
    LI("Ik ga naar een concert. En u, waar gaat u heen?", ["Ik ga naar een concert. En u, waar gaat u heen","Ik ga naar een concert en u waar gaat u heen"], "Vou a um concerto. E o senhor, para onde vai?", "Devolver a pergunta.", ["v-en-jij"]),
    WO("Também vai a caminho de Amesterdão?", ["Bent","u","ook","onderweg","naar","Amsterdam?"], "Pergunta.", ["v-ook-onderweg"]),
    AR("onbekende","o desconhecido","de", "De onbekende.", ["v-onbekende"]),
  ], diff=3, mins=7)

L(11, "Contar uma história engraçada", "Moet je horen wat mij overkwam!",
  ["Contar uma anedota pessoal de forma viva"],
  vocab=[V("v-moet-je-horen","moet je horen","olha só|ouve esta","expression"), V("v-grappig","grappig","engraçado","adjective"),
         V("v-en-toen","en toen …","e então …","expression"), V("v-dubbel-liggen","dubbel liggen (van het lachen)","morrer de riso","expression")],
  ex=[("Moet je horen wat mij gisteren overkwam!","Olha só o que me aconteceu ontem!"),("Het was zo grappig.","Foi tão engraçado."),("En toen? Wat gebeurde er toen?","E então? O que aconteceu a seguir?"),("We lagen dubbel van het lachen.","Morremos de riso.")],
  review=["v-overkomen","v-opeens"],
  cefr=C, exs=[
    MA([("moet je horen","olha só"),("grappig","engraçado"),("en toen …","e então …"),("dubbel liggen","morrer de riso")], "Anedotas.", ["v-moet-je-horen","v-grappig","v-en-toen","v-dubbel-liggen"]),
    CO("dialogue","Een grappig verhaal", "Sofia: Moet je horen wat mij gisteren overkwam!\nLars: Vertel!\nSofia: Ik was bij de bakker en ik wilde «een half bruin» bestellen. Maar ik zei «een halve bruid».\nLars: Haha! En toen?\nSofia: De bakker keek me heel serieus aan en zei: «Die hebben we helaas niet, mevrouw.»\nLars: Geweldig! Ik lig dubbel.",
       [("O que queria pedir a Sofia?", ["*Meio pão escuro","Uma noiva","Um bolo"]),("O que disse por engano?", ["*«Meia noiva»","«Pão branco»","«Obrigada»"]),("Como reagiu o padeiro?", ["*Respondeu muito sério que não tinham","Riu-se muito","Não percebeu"])],
       "Humor com um erro de pronúncia (bruin/bruid).", ["v-moet-je-horen","v-en-toen","v-dubbel-liggen"]),
    TR("pt-nl","Olha só o que me aconteceu!", ["Moet je horen wat mij overkwam","Moet je horen wat me overkwam","Moet je horen wat mij is overkomen"], "Abertura de anedota.", ["v-moet-je-horen"]),
    TR("pt-nl","Foi tão engraçado.", ["Het was zo grappig"], "grappig.", ["v-grappig"]),
    MC("O ouvinte mostra interesse dizendo…", ["*En toen? Vertel!","Saai.|Desinteressado.","Ik moet gaan.|Interrompe."], "Reações de ouvinte.", ["v-en-toen"]),
    FE(["Het","was","zo","grappige!"], 3, "grappig", "Predicativo: grappig.", ["v-grappig"]),
    FB("We lagen ___ van het lachen.", ["dubbel"], "Morrer de riso.", ["v-dubbel-liggen"], choices=["dubbel","grappig","hard"], tr="Morremos de riso."),
    LI("Je raadt nooit wie ik vandaag tegenkwam!", ["Je raadt nooit wie ik vandaag tegenkwam","Je raadt nooit wie ik vandaag tegenkwam!"], "Nunca vais adivinhar com quem me cruzei hoje!", "tegenkomen = cruzar-se com.", ["v-moet-je-horen"]),
    WO("E então? O que aconteceu?", ["En","toen?","Wat","gebeurde","er?"], "Perguntas curtas.", ["v-en-toen"]),
    SW("Conte uma pequena história engraçada (4–6 frases) que lhe aconteceu, começando com «Moet je horen…».", ["Moet je horen wat mij vorige week overkwam! Ik zat in de trein en ik viel in slaap. Toen ik wakker werd, lag mijn hoofd op de schouder van een onbekende man. Ik schaamde me dood, maar hij lachte en zei: «U sliep zo lekker, ik wilde u niet wakker maken.» We lagen allebei dubbel van het lachen."], ["Abertura «Moet je horen»", "Passado", "Final com reação"], 40, "Anedota.", ["v-moet-je-horen","v-grappig"]),
  ], diff=3, mins=7)

L(12, "Mostrar interesse", "Echt waar? Wat leuk! Hoe was dat?",
  ["Reagir com interesse e fazer perguntas de seguimento"],
  vocab=[V("v-echt-waar","echt waar?","a sério?","expression"), V("v-hoe-was-dat","hoe was dat?","como foi isso?","expression"),
         V("v-vervolgvraag","vervolgvraag","pergunta de seguimento","noun","de"), V("v-wat-leuk","wat leuk!","que giro!|que bom!","expression")],
  ex=[("Ik ben net terug uit Japan. — Echt waar? Hoe was dat?","Acabei de voltar do Japão. — A sério? Como foi?"),("Wat leuk dat je weer terug bent!","Que bom que voltaste!"),("Stel een vervolgvraag om interesse te tonen.","Faz uma pergunta de seguimento para mostrar interesse.")],
  review=["v-goh","v-meen-je-dat","v-o-ja"],
  cefr=C, exs=[
    MA([("echt waar?","a sério?"),("hoe was dat?","como foi?"),("vervolgvraag","pergunta de seguimento"),("wat leuk!","que giro!")], "Interesse.", ["v-echt-waar","v-hoe-was-dat","v-vervolgvraag","v-wat-leuk"]),
    DL([("Collega","Ik heb dit weekend leren surfen.","Este fim de semana aprendi a fazer surf."),("Jij","","")], ["*Echt waar? Wat leuk! Was het moeilijk?","O.|Desinteressado.","Ik surf niet.|Corta a conversa."], "Reagir + pergunta de seguimento.", ["v-echt-waar","v-wat-leuk"]),
    DL([("Buurvrouw","Mijn kleindochter is gisteren geboren!","A minha neta nasceu ontem!"),("Jij","","")], ["*Gefeliciteerd! Hoe heet ze?","Goh.|Pouco entusiasmado.","Echt waar? Ik ook.|Não faz sentido."], "Felicitar e perguntar.", ["v-vervolgvraag"]),
    MC("Qual é uma boa pergunta de seguimento para «Ik ben net verhuisd»?", ["*O, waar woon je nu?","Oké.|Fecha a conversa.","Ik ook niet.|Não faz sentido."], "Perguntas abertas.", ["v-vervolgvraag"]),
    TR("pt-nl","A sério? Como foi?", ["Echt waar? Hoe was dat","Echt waar? Hoe was het","Echt? Hoe was het"], "Reação + pergunta.", ["v-echt-waar","v-hoe-was-dat"]),
    TR("pt-nl","Que bom que voltaste!", ["Wat leuk dat je weer terug bent","Wat leuk dat je terug bent","Wat fijn dat je weer terug bent"], "Wat leuk dat…", ["v-wat-leuk"]),
    FE(["Wat","leuke","dat","je","er","bent!"], 1, "leuk", "Wat leuk (sem -e) dat…", ["v-wat-leuk"]),
    FB("Een goede ___ laat zien dat je echt luistert.", ["vervolgvraag"], "Pergunta de seguimento.", ["v-vervolgvraag"], choices=["vervolgvraag","antwoord","praatje"], tr="Uma boa pergunta de seguimento mostra que estás mesmo a ouvir."),
    LI("Goh, dat wist ik niet. Hoe lang woon je daar al?", ["Goh, dat wist ik niet. Hoe lang woon je daar al","Goh dat wist ik niet hoe lang woon je daar al"], "Olha, não sabia. Há quanto tempo vives lá?", "goh = olha/caramba.", ["v-goh"]),
    WO("Como foi isso?", ["Hoe","was","dat?"], "Pergunta curta.", ["v-hoe-was-dat"]),
  ], diff=3, mins=6)

L(13, "Mudar de assunto", "Over iets anders gesproken …",
  ["Mudar de assunto com naturalidade"],
  vocab=[V("v-over-iets-anders","over iets anders gesproken","mudando de assunto","expression"), V("v-dat-brengt-me-op","dat brengt me op …","isso faz-me lembrar …","expression"),
         V("v-van-onderwerp-veranderen","van onderwerp veranderen","mudar de assunto","expression")],
  ex=[("Over iets anders gesproken: ga je nog op vakantie?","Mudando de assunto: ainda vais de férias?"),("Dat brengt me op een idee!","Isso dá-me uma ideia!"),("Laten we van onderwerp veranderen.","Vamos mudar de assunto.")],
  review=["v-onderwerp","v-over-gesproken","v-trouwens"],
  cefr=C, exs=[
    MA([("over iets anders gesproken","mudando de assunto"),("dat brengt me op …","isso faz-me lembrar …"),("onderwerp","assunto"),("trouwens","a propósito")], "Mudar de assunto.", ["v-over-iets-anders","v-dat-brengt-me-op","v-onderwerp","v-trouwens"]),
    MC("Qual destas ligações é mais suave (liga ao tema anterior)?", ["*Over vakantie gesproken: ga jij nog weg?","Ander onderwerp!|Brusco.","Stop, iets anders.|Rude."], "over … gesproken.", ["v-over-gesproken"]),
    TR("pt-nl","Mudando de assunto: ainda vais de férias?", ["Over iets anders gesproken: ga je nog op vakantie","Over iets anders gesproken, ga je nog op vakantie"], "Expressão.", ["v-over-iets-anders"]),
    TR("pt-nl","Vamos mudar de assunto.", ["Laten we van onderwerp veranderen","Laten we over iets anders praten"], "laten we.", ["v-van-onderwerp-veranderen"]),
    CO("dialogue","Bij de koffie", "Eva: …en daarom ben ik dus gestopt met de sportschool.\nNuno: Begrijpelijk. Over sport gesproken: heb je de wedstrijd van Ajax gezien?\nEva: Nee, ik volg voetbal niet zo. Trouwens, dat brengt me op iets: mijn broer zoekt nog iemand voor zijn zaalvoetbalteam. Heb je zin?\nNuno: Misschien! Wanneer spelen ze?",
       [("Porque deixou a Eva o ginásio?", ["*O texto não diz (conversa já a meio)","Era caro","Lesionou-se"]),("Como muda o Nuno de assunto?", ["*Liga o desporto ao futebol","Muda bruscamente","Não muda"]),("O que propõe a Eva?", ["*Jogar futsal na equipa do irmão","Ir ao estádio","Voltar ao ginásio"])],
       "Transições naturais.", ["v-over-gesproken","v-dat-brengt-me-op","v-trouwens"]),
    AR("onderwerp","o assunto","het", "Het onderwerp.", ["v-onderwerp"]),
    FE(["Over","iets","anders","gesproken:","hoe","gaat","met","je","moeder?"], 6, "het met", "Expressão: hoe gaat het met…", ["v-over-iets-anders"]),
    FB("Dat ___ me op een idee: laten we samen koken!", ["brengt"], "Isso dá-me uma ideia.", ["v-dat-brengt-me-op"], choices=["brengt","neemt","geeft"], tr="Isso dá-me uma ideia: vamos cozinhar juntos!"),
    LI("Trouwens, heb je al gehoord dat Marieke gaat verhuizen?", ["Trouwens, heb je al gehoord dat Marieke gaat verhuizen","Trouwens heb je al gehoord dat Marieke gaat verhuizen"], "A propósito, já ouviste que a Marieke se vai mudar?", "trouwens.", ["v-trouwens"]),
    WO("Isso dá-me uma ideia!", ["Dat","brengt","me","op","een","idee!"], "Expressão.", ["v-dat-brengt-me-op"]),
  ], diff=3, mins=6)

L(14, "Onde é que eu ia?", "Waar was ik gebleven?",
  ["Retomar o fio da conversa depois de uma interrupção"],
  vocab=[V("v-waar-was-ik","waar was ik (gebleven)?","onde é que eu ia?","expression"), V("v-de-draad-oppakken","de draad weer oppakken","retomar o fio","expression"),
         V("v-zoals-ik-al-zei","zoals ik al zei","como eu estava a dizer","expression"), V("v-om-terug-te-komen-op","om terug te komen op …","voltando a …","expression")],
  ex=[("Sorry, waar was ik gebleven?","Desculpa, onde é que eu ia?"),("Zoals ik al zei, het was een lange dag.","Como eu estava a dizer, foi um dia longo."),("Om terug te komen op je vraag: ja, ik kom.","Voltando à tua pergunta: sim, vou.")],
  review=["v-onderbreken"],
  cefr=C, exs=[
    MA([("waar was ik?","onde é que eu ia?"),("de draad weer oppakken","retomar o fio"),("zoals ik al zei","como estava a dizer"),("om terug te komen op","voltando a")], "Retomar.", ["v-waar-was-ik","v-de-draad-oppakken","v-zoals-ik-al-zei","v-om-terug-te-komen-op"]),
    TR("pt-nl","Desculpa, onde é que eu ia?", ["Sorry, waar was ik gebleven","Sorry, waar was ik","Sorry waar was ik gebleven"], "Fórmula.", ["v-waar-was-ik"]),
    TR("pt-nl","Como eu estava a dizer, foi um dia longo.", ["Zoals ik al zei, het was een lange dag","Zoals ik al zei, was het een lange dag"], "zoals ik al zei.", ["v-zoals-ik-al-zei"]),
    CO("dialogue","Onderbroken", "Ana: …en toen ik bij het station aankwam, zag ik dat—\n(Telefoon gaat.)\nAna: Sorry, even opnemen. … Zo. Waar was ik gebleven?\nJoost: Je kwam bij het station aan.\nAna: O ja! Zoals ik al zei: ik kwam aan en zag dat alle treinen waren uitgevallen.\nJoost: Wat vervelend! En toen?",
       [("O que interrompeu a Ana?", ["*O telefone","Uma pessoa","O comboio"]),("Quem a ajuda a retomar?", ["*O Joost","Ninguém","A mãe"]),("O que viu na estação?", ["*Todos os comboios cancelados","Um amigo","Um acidente"])],
       "Retomar depois de interrupção.", ["v-waar-was-ik","v-zoals-ik-al-zei"]),
    FB("Om terug te komen ___ je vraag: ja, dat kan.", ["op"], "terugkomen op.", ["v-om-terug-te-komen-op"], choices=["op","naar","aan"], tr="Voltando à tua pergunta: sim, é possível."),
    FE(["Zoals","ik","al","zegt,","het","was","koud."], 3, "zei", "Passado: zoals ik al zei.", ["v-zoals-ik-al-zei"]),
    MC("Alguém o ajuda dizendo «Je had het over je reis». Isso significa…", ["*Estavas a falar da tua viagem","Fizeste uma viagem|Não exatamente.","Vais viajar|Não."], "het hebben over = falar de.", ["v-de-draad-oppakken"]),
    LI("Na de pauze pakten we de draad weer op.", ["Na de pauze pakten we de draad weer op"], "Depois da pausa retomámos o fio.", "oppakken.", ["v-de-draad-oppakken"]),
    WO("Onde é que eu ia?", ["Waar","was","ik","gebleven?"], "Pergunta.", ["v-waar-was-ik"]),
    DL([("Collega","Sorry dat ik je onderbrak. Ga verder!","Desculpa ter-te interrompido. Continua!"),("Jij","","")], ["*Geen probleem. Om terug te komen op het budget: we hebben te weinig geld.","Ik onderbrak niet.|Não faz sentido.","Ga verder!|Repete."], "Retomar.", ["v-om-terug-te-komen-op"]),
  ], diff=3, mins=6)

L(15, "Palavras de enchimento", "Nou, weet je, zeg maar …",
  ["Usar palavras de enchimento típicas da fala para soar natural"],
  vocab=[V("v-zeg-maar","zeg maar","tipo|digamos","expression"), V("v-weet-je","weet je","sabes","expression"),
         V("v-gewoon","gewoon","simplesmente","adverb")],
  ex=[("Het was, zeg maar, een soort feest.","Foi, tipo, uma espécie de festa."),("Weet je, ik heb er eigenlijk geen zin in.","Sabes, na verdade não me apetece."),("Ik doe het gewoon morgen.","Faço simplesmente amanhã.")],
  review=["v-eigenlijk","v-een-soort","v-even-denken"],
  cefr=C, exs=[
    MA([("zeg maar","tipo/digamos"),("weet je","sabes"),("eigenlijk","na verdade"),("gewoon","simplesmente")], "Enchimento.", ["v-zeg-maar","v-weet-je","v-eigenlijk","v-gewoon"]),
    MC("Palavras como «zeg maar» e «weet je» são…", ["*normais na fala informal, mas não se usam numa carta formal","erros de gramática|Não.","só usadas por crianças|Não."], "Registo oral.", ["v-zeg-maar","v-weet-je"]),
    LI("Het was, zeg maar, een soort picknick in het park.", ["Het was, zeg maar, een soort picknick in het park","Het was zeg maar een soort picknick in het park"], "Foi, tipo, uma espécie de piquenique no parque.", "Enchimento.", ["v-zeg-maar"]),
    LI("Weet je, ik denk dat ik gewoon thuisblijf.", ["Weet je, ik denk dat ik gewoon thuisblijf","Weet je ik denk dat ik gewoon thuisblijf"], "Sabes, acho que simplesmente fico em casa.", "gewoon.", ["v-weet-je","v-gewoon"]),
    TR("pt-nl","Faço simplesmente amanhã.", ["Ik doe het gewoon morgen","Ik doe het morgen gewoon"], "gewoon.", ["v-gewoon"]),
    MC("«Gewoon» também significa…", ["*normal/comum","grande|Não.","rápido|Não."], "Een gewone dag = um dia normal.", ["v-gewoon"]),
    FB("Ik heb er ___ geen tijd voor, sorry.", ["eigenlijk"], "Na verdade.", ["v-eigenlijk"], choices=["eigenlijk","zeg","weet"], tr="Na verdade não tenho tempo para isso, desculpa."),
    FE(["Het","was","een","gewone","dag","en","ik","werkte","gewone."], 8, "gewoon", "Advérbio: gewoon (sem -e).", ["v-gewoon"]),
    CO("dialogue","Een informeel gesprek", "Bas: Hoe was het feest?\nMila: Nou, eigenlijk best leuk. Het was, zeg maar, meer een etentje dan een feest.\nBas: O ja?\nMila: Ja, weet je, er waren maar tien mensen. Gewoon gezellig met elkaar eten.",
       [("Como foi a festa?", ["*Na verdade bastante gira","Aborrecida","Não foi"]),("Era mais o quê?", ["*Um jantar","Uma discoteca","Uma reunião"]),("Quantas pessoas?", ["*Dez","Cem","Duas"])],
       "Enchimento na fala.", ["v-zeg-maar","v-weet-je","v-gewoon"]),
    WO("Foi tipo uma festa.", ["Het","was","zeg","maar","een","feest"], "Enchimento no meio.", ["v-zeg-maar"]),
  ], diff=3, mins=6)

