    MC("Ordem de gravidade: para algo leve (perdeu o autocarro) diz-se…", ["*Wat vervelend!","Gecondoleerd.|Para morte.","Wat verschrikkelijk!|Exagerado."], "Adequar a reação.", ["v-wat-vervelend"]),
    TR("pt-nl","Posso fazer alguma coisa por ti?", ["Kan ik iets voor je doen","Kan ik iets voor jou doen","Kan ik je ergens mee helpen"], "Oferta.", ["v-kan-ik-iets-doen"]),
